import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(in.readLine());
        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        long totalCells = N * M;
        long colorCount = R - L + 1;
        long power = power(colorCount, totalCells);

        if (totalCells % 2 == 1) {
            out.println(power);
        } else if (colorCount % 2 == 0) {
            out.println(power * ((MOD + 1) / 2) % MOD);
        } else {
            out.println((power + 1) * ((MOD + 1) / 2) % MOD);
        }

        in.close();
        out.close();
    }

    private static long power(long base, long exponent) {
        if (exponent <= 0L) {
            return 1L;
        }
        long result = 1L;
        long bit = Long.highestOneBit(exponent);
        while (bit != 0L) {
            result = result * result % MOD;
            if ((exponent & bit) != 0L) {
                result = result * base % MOD;
            }
            bit >>= 1;
        }
        return result;
    }
}
